// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetStorageReport What the corpus costs, and whether the disk agrees with the database.
	// (GET /admin/storage)
	GetStorageReport(w http.ResponseWriter, r *http.Request)
	// GetTranscriptionReport How transcription is going, and which memos are stuck.
	// (GET /admin/transcription)
	GetTranscriptionReport(w http.ResponseWriter, r *http.Request)
	// GetTriageReport What triage left behind — the backlog by age, and the decisions that did not finish landing.
	// (GET /admin/triage)
	GetTriageReport(w http.ResponseWriter, r *http.Request)
	// ListUsers Every account, with its devices and invite state.
	// (GET /admin/users)
	ListUsers(w http.ResponseWriter, r *http.Request)
	// CreateUser Create an account and mint its first invite.
	// (POST /admin/users)
	CreateUser(w http.ResponseWriter, r *http.Request)
	// DeleteUser Remove an account and its credentials.
	// (DELETE /admin/users/{id})
	DeleteUser(w http.ResponseWriter, r *http.Request, id UserId)
	// CreateUserInvite Mint a fresh invite for an existing account.
	// (POST /admin/users/{id}/invite)
	CreateUserInvite(w http.ResponseWriter, r *http.Request, id UserId)
	// CreateSelfInvite Mint an invite for another of your own devices.
	// (POST /auth/invite)
	CreateSelfInvite(w http.ResponseWriter, r *http.Request)
	// GetMe The account this session belongs to.
	// (GET /auth/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Change your own display name.
	// (PATCH /auth/me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// DeleteSession Sign out, revoking this session.
	// (DELETE /auth/session)
	DeleteSession(w http.ResponseWriter, r *http.Request)
	// CreateSession Redeem an invite for a session.
	// (POST /auth/session)
	CreateSession(w http.ResponseWriter, r *http.Request)
	// ListSessions Your own signed-in devices.
	// (GET /auth/sessions)
	ListSessions(w http.ResponseWriter, r *http.Request)
	// RevokeSession Revoke one of your own sessions.
	// (DELETE /auth/sessions/{id})
	RevokeSession(w http.ResponseWriter, r *http.Request, id SessionId)
	// CreateSessionFromAccess Exchange a verified Cloudflare Access identity for a session.
	// (POST /auth/sso/cloudflare)
	CreateSessionFromAccess(w http.ResponseWriter, r *http.Request)
	// ListDiscussions The threads filed against a page.
	// (GET /discussions)
	ListDiscussions(w http.ResponseWriter, r *http.Request, params ListDiscussionsParams)
	// OpenDiscussion Open a thread with its first turn.
	// (POST /discussions)
	OpenDiscussion(w http.ResponseWriter, r *http.Request)
	// ListUnread The badge — every thread this account has something unread in.
	// (GET /discussions/unread)
	ListUnread(w http.ResponseWriter, r *http.Request)
	// GetDiscussion A thread, in order, with its participants and your unread count.
	// (GET /discussions/{ref})
	GetDiscussion(w http.ResponseWriter, r *http.Request, ref DiscussionRef)
	// AddParticipant Put an account on a thread — a person, or the Scribe.
	// (POST /discussions/{ref}/participants)
	AddParticipant(w http.ResponseWriter, r *http.Request, ref DiscussionRef)
	// RemoveParticipant Take an account off a thread, without touching a word they said.
	// (DELETE /discussions/{ref}/participants/{id})
	RemoveParticipant(w http.ResponseWriter, r *http.Request, ref DiscussionRef, id UserId)
	// MarkRead Report how far you have read.
	// (POST /discussions/{ref}/read)
	MarkRead(w http.ResponseWriter, r *http.Request, ref DiscussionRef)
	// ResolveDiscussion Resolve a thread — into a new note, an existing one, or nothing.
	// (POST /discussions/{ref}/resolve)
	ResolveDiscussion(w http.ResponseWriter, r *http.Request, ref DiscussionRef)
	// AppendTurn Reply.
	// (POST /discussions/{ref}/turns)
	AppendTurn(w http.ResponseWriter, r *http.Request, ref DiscussionRef)
	// GetHealthz Liveness. No dependencies, no credential.
	// (GET /healthz)
	GetHealthz(w http.ResponseWriter, r *http.Request)
	// OpenUpload Declare an upload and open a session for it.
	// (POST /memos/uploads)
	OpenUpload(w http.ResponseWriter, r *http.Request)
	// AbandonUpload Abandon an upload and discard its staged bytes.
	// (DELETE /memos/uploads/{id})
	AbandonUpload(w http.ResponseWriter, r *http.Request, id UploadId)
	// GetUpload Where this upload got to.
	// (GET /memos/uploads/{id})
	GetUpload(w http.ResponseWriter, r *http.Request, id UploadId)
	// AppendChunk Append a chunk.
	// (PATCH /memos/uploads/{id})
	AppendChunk(w http.ResponseWriter, r *http.Request, id UploadId, params AppendChunkParams)
	// ListNotes The live notes filed on a page.
	// (GET /notes)
	ListNotes(w http.ResponseWriter, r *http.Request, params ListNotesParams)
	// CreateNote Create a note, as the authenticated person.
	// (POST /notes)
	CreateNote(w http.ResponseWriter, r *http.Request)
	// GetNote A note, rendered, with the references its text names.
	// (GET /notes/{ref})
	GetNote(w http.ResponseWriter, r *http.Request, ref NoteRef, params GetNoteParams)
	// ListNoteBacklinks The notes whose text names this one, resolved.
	// (GET /notes/{ref}/backlinks)
	ListNoteBacklinks(w http.ResponseWriter, r *http.Request, ref NoteRef, params ListNoteBacklinksParams)
	// ListNoteRevisions A note's history, oldest first, with each revision's text.
	// (GET /notes/{ref}/revisions)
	ListNoteRevisions(w http.ResponseWriter, r *http.Request, ref NoteRef, params ListNoteRevisionsParams)
	// AppendRevision Append a revision.
	// (POST /notes/{ref}/revisions)
	AppendRevision(w http.ResponseWriter, r *http.Request, ref NoteRef)
	// ListPages The whole page tree, as sorted paths.
	// (GET /pages)
	ListPages(w http.ResponseWriter, r *http.Request)
	// CreatePage Create a page at a path.
	// (POST /pages)
	CreatePage(w http.ResponseWriter, r *http.Request)
	// GetReadyz Readiness. Pings the database.
	// (GET /readyz)
	GetReadyz(w http.ResponseWriter, r *http.Request)
	// ResolveReferences Resolve a batch of references into live cards.
	// (POST /references/resolve)
	ResolveReferences(w http.ResponseWriter, r *http.Request)
	// Search Full-text search across notes and transcripts.
	// (GET /search)
	Search(w http.ResponseWriter, r *http.Request, params SearchParams)
	// GetTier1Page One page of the generated estate wiki, rendered.
	// (GET /tier1/page)
	GetTier1Page(w http.ResponseWriter, r *http.Request, params GetTier1PageParams)
	// ListTier1Pages Every page of the generated estate wiki.
	// (GET /tier1/pages)
	ListTier1Pages(w http.ResponseWriter, r *http.Request)
	// AcceptTriage Confirm a batch of decisions.
	// (POST /triage/accept)
	AcceptTriage(w http.ResponseWriter, r *http.Request)
	// GetTriageBatch The next memos awaiting a decision, with their proposals.
	// (GET /triage/batch)
	GetTriageBatch(w http.ResponseWriter, r *http.Request, params GetTriageBatchParams)
	// ListDeferred What this account has deferred, oldest first.
	// (GET /triage/deferred)
	ListDeferred(w http.ResponseWriter, r *http.Request, params ListDeferredParams)
	// HoldMemo Defer a memo — "not now".
	// (POST /triage/hold)
	HoldMemo(w http.ResponseWriter, r *http.Request)
	// ReleaseMemo Bring a deferred memo back into the batch.
	// (POST /triage/release)
	ReleaseMemo(w http.ResponseWriter, r *http.Request)
}

